#include <bits/stdc++.h>
using namespace std;

inline int gcd(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

struct Node {
    long long ans;
    int total_gcd;
    int pref_len;
    int pref_g[32];
    int pref_cnt[32];
    int suff_len;
    int suff_g[32];
    int suff_cnt[32];
};

Node combine(const Node& L, const Node& R) {
    if (L.pref_len == 0) return R;
    if (R.pref_len == 0) return L;
    Node res;
    res.total_gcd = gcd(L.total_gcd, R.total_gcd);
    res.ans = L.ans + R.ans;
    // cross
    for (int i = 0; i < L.suff_len; ++i) {
        int g1 = L.suff_g[i];
        if (g1 == 1) break;
        int c1 = L.suff_cnt[i];
        for (int j = 0; j < R.pref_len; ++j) {
            int g2 = R.pref_g[j];
            if (g2 == 1) break;
            if (gcd(g1, g2) > 1) {
                res.ans += 1LL * c1 * R.pref_cnt[j];
            }
        }
    }
    // pref
    res.pref_len = 0;
    for (int i = 0; i < L.pref_len; ++i) {
        res.pref_g[res.pref_len] = L.pref_g[i];
        res.pref_cnt[res.pref_len] = L.pref_cnt[i];
        res.pref_len++;
    }
    for (int i = 0; i < R.pref_len; ++i) {
        int new_g = gcd(L.total_gcd, R.pref_g[i]);
        int cnt = R.pref_cnt[i];
        if (res.pref_len > 0 && res.pref_g[res.pref_len-1] == new_g) {
            res.pref_cnt[res.pref_len-1] += cnt;
        } else {
            res.pref_g[res.pref_len] = new_g;
            res.pref_cnt[res.pref_len] = cnt;
            res.pref_len++;
        }
    }
    // suff
    res.suff_len = 0;
    for (int i = 0; i < R.suff_len; ++i) {
        res.suff_g[res.suff_len] = R.suff_g[i];
        res.suff_cnt[res.suff_len] = R.suff_cnt[i];
        res.suff_len++;
    }
    for (int i = 0; i < L.suff_len; ++i) {
        int new_g = gcd(R.total_gcd, L.suff_g[i]);
        int cnt = L.suff_cnt[i];
        if (res.suff_len > 0 && res.suff_g[res.suff_len-1] == new_g) {
            res.suff_cnt[res.suff_len-1] += cnt;
        } else {
            res.suff_g[res.suff_len] = new_g;
            res.suff_cnt[res.suff_len] = cnt;
            res.suff_len++;
        }
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, M;
    cin >> N >> M;
    vector<int> S(N+1);
    for (int i = 1; i <= N; ++i) cin >> S[i];
    int size = 1;
    while (size < N) size <<= 1;
    vector<Node> tree(2*size);
    for (int i = 0; i < 2*size; ++i) {
        tree[i].pref_len = 0;
        tree[i].suff_len = 0;
        tree[i].ans = 0;
        tree[i].total_gcd = 1;
    }
    for (int i = 1; i <= N; ++i) {
        int idx = size + i - 1;
        int v = S[i];
        tree[idx].total_gcd = v;
        tree[idx].ans = (v > 1) ? 1 : 0;
        tree[idx].pref_len = 1;
        tree[idx].pref_g[0] = v;
        tree[idx].pref_cnt[0] = 1;
        tree[idx].suff_len = 1;
        tree[idx].suff_g[0] = v;
        tree[idx].suff_cnt[0] = 1;
    }
    for (int i = size - 1; i >= 1; --i) {
        tree[i] = combine(tree[2*i], tree[2*i+1]);
    }
    while (M--) {
        int T;
        cin >> T;
        if (T == 1) {
            int I, V;
            cin >> I >> V;
            int idx = size + I - 1;
            tree[idx].total_gcd = V;
            tree[idx].ans = (V > 1) ? 1 : 0;
            tree[idx].pref_len = 1;
            tree[idx].pref_g[0] = V;
            tree[idx].pref_cnt[0] = 1;
            tree[idx].suff_len = 1;
            tree[idx].suff_g[0] = V;
            tree[idx].suff_cnt[0] = 1;
            idx >>= 1;
            while (idx >= 1) {
                tree[idx] = combine(tree[2*idx], tree[2*idx+1]);
                idx >>= 1;
            }
        } else {
            int E, D;
            cin >> E >> D;
            int l = size + E - 1;
            int r = size + D - 1;
            Node left_res, right_res;
            bool has_left = false, has_right = false;
            while (l <= r) {
                if (l & 1) {
                    if (!has_left) {
                        left_res = tree[l];
                        has_left = true;
                    } else {
                        left_res = combine(left_res, tree[l]);
                    }
                    l++;
                }
                if (!(r & 1)) {
                    if (!has_right) {
                        right_res = tree[r];
                        has_right = true;
                    } else {
                        right_res = combine(tree[r], right_res);
                    }
                    r--;
                }
                l >>= 1;
                r >>= 1;
            }
            Node res;
            if (!has_left) res = right_res;
            else if (!has_right) res = left_res;
            else res = combine(left_res, right_res);
            cout << res.ans << '\n';
        }
    }
    return 0;
}
